globalThis.LAYER_DATA = {"poolInput":"","poolOutput":"","flattenInput":"","flattenOutput":"","denseInput":"","denseWeights":"","denseBias":"","denseOutput":"","dense2Weights":"","dense2Bias":"","softmaxOutput":"","sources":{"pool":{"path":"cpre487lab2/src/layers/MaxPooling.h","start":11,"code":"    MaxPoolingLayer(const LayerParams inParams, const LayerParams outParams) : Layer(inParams, outParams, LayerType::MAX_POOLING) {}\n\n    // Each output value is the maximum of one window of the same input channel\n    virtual void computeNaive(const LayerData& dataIn) const override {\n        // Input (H, W, C), output (P, Q, C)\n        const dimVec& inDims = getInputParams().dims;\n        const dimVec& outDims = getOutputParams().dims;\n\n        const size H = inDims[0], W = inDims[1], C = inDims[2];\n        const size P = outDims[0], Q = outDims[1];\n\n        // Window size in each direction (2 x 2 for every pooling layer of our model)\n        const size R = H / P, S = W / Q;\n\n        LayerData& dataOut = getOutputData();\n\n        for (size p = 0; p < P; p++) {\n            for (size q = 0; q < Q; q++) {\n                for (size c = 0; c < C; c++) {\n                    fp32 maxValue = dataIn.get<fp32>(((p * R) * W + (q * S)) * C + c);\n\n                    for (size r = 0; r < R; r++) {\n                        for (size s = 0; s < S; s++) {\n                            const fp32 value = dataIn.get<fp32>(((p * R + r) * W + (q * S + s)) * C + c);\n                            if (value > maxValue) maxValue = value;\n                        }\n                    }\n\n                    dataOut.get<fp32>((p * Q + q) * C + c) = maxValue;\n                }\n            }\n        }\n    }"},"flatten":{"path":"cpre487lab2/src/layers/Flatten.h","start":10,"code":"// Flatten (H, W, C) into one vector of H * W * C values\nclass FlattenLayer : public Layer {\n   public:\n    // The framework has no layer type for flatten, so LayerType::NONE is used\n    FlattenLayer(const LayerParams inParams, const LayerParams outParams) : Layer(inParams, outParams, LayerType::NONE) {}\n\n    // Feature maps are already stored as one array in (H, W, C) order, which is the order Keras flattens in,\n    // so the values are copied unchanged and only the dimensions differ\n    virtual void computeNaive(const LayerData& dataIn) const override {\n        std::memcpy(getOutputData().raw(), dataIn.raw(), getOutputParams().byte_size());\n    }\n\n    // Only the naive implementation is required for this lab\n    virtual void computeThreaded(const LayerData& dataIn) const override { computeNaive(dataIn); }\n    virtual void computeTiled(const LayerData& dataIn) const override { computeNaive(dataIn); }\n    virtual void computeSIMD(const LayerData& dataIn) const override { computeNaive(dataIn); }\n};"},"dense":{"path":"cpre487lab2/src/layers/Dense.h","start":36,"code":"        Layer::freeLayer();\n        weightData.freeData();\n        biasData.freeData();\n    }\n\n    virtual void computeNaive(const LayerData& dataIn) const override {\n        // Input (N), weights (N, M), output (M)\n        const size N = getInputParams().dims[0];\n        const size M = getOutputParams().dims[0];\n\n        LayerData& dataOut = getOutputData();\n\n        for (size m = 0; m < M; m++) {\n            fp32 sum = biasData.get<fp32>(m);\n\n            for (size n = 0; n < N; n++) {\n                sum += dataIn.get<fp32>(n) * weightData.get<fp32>(n * M + m);\n            }\n\n            dataOut.get<fp32>(m) = (applyRelu && sum < 0) ? 0 : sum;\n        }\n    }"},"softmax":{"path":"cpre487lab2/src/layers/Softmax.h","start":10,"code":"// Softmax activation: Y_i = exp(g_i) / sum over l of exp(g_l)\nclass SoftmaxLayer : public Layer {\n   public:\n    SoftmaxLayer(const LayerParams inParams, const LayerParams outParams) : Layer(inParams, outParams, LayerType::SOFTMAX) {}\n\n    virtual void computeNaive(const LayerData& dataIn) const override {\n        const size N = getInputParams().flat_count();\n\n        LayerData& dataOut = getOutputData();\n\n        // Subtracting the largest input from every input does not change the result (the factor exp(-max) cancels\n        // in the fraction) but keeps exp() from overflowing for large inputs\n        fp32 maxValue = dataIn.get<fp32>(0);\n        for (size i = 1; i < N; i++) {\n            if (dataIn.get<fp32>(i) > maxValue) maxValue = dataIn.get<fp32>(i);\n        }\n\n        fp32 sum = 0;\n        for (size i = 0; i < N; i++) {\n            const fp32 e = std::exp(dataIn.get<fp32>(i) - maxValue);\n            dataOut.get<fp32>(i) = e;\n            sum += e;\n        }\n\n        for (size i = 0; i < N; i++) {\n            dataOut.get<fp32>(i) /= sum;\n        }\n    }\n\n    // Only the naive implementation is required for this lab\n    virtual void computeThreaded(const LayerData& dataIn) const override { computeNaive(dataIn); }\n    virtual void computeTiled(const LayerData& dataIn) const override { computeNaive(dataIn); }\n    virtual void computeSIMD(const LayerData& dataIn) const override { computeNaive(dataIn); }\n};\n\n}  // namespace ML"}}};
